#ifndef __PINS_H__
#define __PINS_H__

#include <../usr/include/pins.h>
#include <stdint.h>
#include <assert.h>

typedef struct PinNode {
  void *ptr;
  uint8_t data;
  uint8_t vector_len;
  uint8_t bit_offset;
} PinNode;
extern PinNode pin_array[];

// A vector signal is held by an integer object just wide enough to contain it,
// e.g. the CData/SData/IData/QData port types generated by Verilator. Access
// it with the matching width, so that binding a vector never reads or writes
// memory outside of the signal object (which would also break the alignment
// requirement of the access).
static inline uint64_t pin_read(const void *ptr, int len) {
  if (len <= 8) return *(const uint8_t *)ptr;
  if (len <= 16) return *(const uint16_t *)ptr;
  if (len <= 32) return *(const uint32_t *)ptr;
  return *(const uint64_t *)ptr;
}

static inline void pin_write(void *ptr, int len, uint64_t v) {
  if (len <= 8) *(uint8_t *)ptr = (uint8_t)v;
  else if (len <= 16) *(uint16_t *)ptr = (uint16_t)v;
  else if (len <= 32) *(uint32_t *)ptr = (uint32_t)v;
  else *(uint64_t *)ptr = v;
}

static inline uint8_t pin_peek(int pin) {
  PinNode *p = &pin_array[pin];
  if (p->vector_len == 1) {
    return *(uint8_t *)p->ptr & 1;
  } else {
    uint64_t v = pin_read(p->ptr, p->vector_len);
    return (v >> p->bit_offset) & 1;
  }
}

static inline void pin_poke(int pin, uint64_t v) {
  PinNode *p = &pin_array[pin];
  if (p->vector_len == 1) {
    *(uint8_t *)p->ptr = v & 1;
  } else {
    uint64_t x = pin_read(p->ptr, p->vector_len);
    uint64_t mask = (uint64_t)1 << p->bit_offset;
    pin_write(p->ptr, p->vector_len, (x & ~mask) | ((v & 1) << p->bit_offset));
  }
}

#endif
